@push('scripts')
<script>
(function(){
 document.querySelectorAll('[data-copy-number]').forEach(function(button){button.addEventListener('click',function(){var value=button.getAttribute('data-copy-number')||'';function done(){button.innerHTML='<i class="fas fa-check"></i> কপি হয়েছে';setTimeout(function(){button.innerHTML='<i class="far fa-copy"></i> কপি';},1600);}if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(value).then(done,function(){fallbackCopy(value,done);});}else{fallbackCopy(value,done);}});});
 function fallbackCopy(value,done){var input=document.createElement('textarea');input.value=value;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();try{document.execCommand('copy');done();}catch(e){}input.remove();}
 var method=document.getElementById('payment_method'),field=document.getElementById('transaction-field'),input=document.getElementById('transaction_reference');if(method&&field&&input){function toggle(){var cash=method.value==='cash_at_chamber';field.style.display=cash?'none':'block';input.required=!!method.value&&!cash;}method.addEventListener('change',toggle);toggle();}
})();
</script>
@endpush
